import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json}from './bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-workbook-pagination',sf=stage+'/SOURCE_CANDIDATE.json',s=json(sf),p=json(s.parent);assert.equal(hash(s.parent),s.parentSha256);
for(const r of s.sourceRows)assert.equal(hash(s.website+'/'+r.path),r.sha256,r.path);
for(const r of p.sourceRows){assert.equal(hash(p.website+'/'+r.path),r.sha256,r.path);if(!s.changedPaths.includes(r.path))assert.equal(hash(s.website+'/'+r.path),r.sha256,r.path);}
const read=(root,n)=>fs.readFileSync(root+'/'+n,'utf8').replaceAll('\r\n','\n');
const css=read(s.website,'components/studio-workspace.css'),rules=css.split('\n').filter(line=>line.startsWith('.studio-workbook-pager'));assert.equal(rules.length,4);let priorCss=css;for(const line of rules){assert.equal(priorCss.split(line+'\n').length,2);priorCss=priorCss.replace(line+'\n','');}assert.equal(priorCss,read(p.website,'components/studio-workspace.css'),'All preceding styles unchanged');
const binding=json(s.website+'/atlas-review/integration-inputs.json');assert.equal(binding.sha256,s.reviewBindingSha256);assert.equal(binding.inputs.length,1835);for(const r of binding.inputs)assert.equal(hash(s.website+'/'+r.path),r.sha256,r.path);
for(const n of ['package.json','package-lock.json','lib/studio-queues.ts','components/StudioForms.tsx','components/StudioCourseEditor.tsx','lib/education-platform.ts'])assert.equal(hash(s.website+'/'+n),hash(p.website+'/'+n),n);
fs.writeFileSync(stage+'/CONTENT_QA.json',JSON.stringify({at:new Date().toISOString(),passing:true,source:{path:sf,sha256:hash(sf)},changedPaths:s.changedPaths,addedPaths:s.addedPaths,allOtherParentSourceExact:true,all1835ReviewInputsExact:true,noAuthApiCourseEditorOrDependenciesChanged:true,existingStylesPreserved:true,clinicalApproval:false,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});console.log('Workbook pagination scope verified; access, forms, source geometry and Review unchanged.');
